{
  "name": "create_customer",
  "description": "Create (or fetch) the customer record for the person you are chatting with. Their phone number is filled in automatically — never ask for it and never pass it yourself. Call this once before create_checkout so the order is linked to them. Returns the same customer if one already exists.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/customers",
    "path_parameters": {},
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "phone": {
          "type": "string",
          "description": "WhatsApp phone number of the current conversation, injected by the runtime.",
          "binding": {
            "kind": "macro",
            "macro": "WHATSAPP_PHONE_NUMBER"
          }
        },
        "name": {
          "type": "string",
          "description": "Customer's name, if they have given it."
        },
        "email": {
          "type": "string",
          "description": "Customer email, only if they volunteer one. Never ask for it just to fill this in — the phone number already identifies them."
        }
      },
      "required": [
        "phone"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "find_customer",
  "description": "Check whether the person you are chatting with is already a customer, without creating anything. Their phone number is filled in automatically — never ask for it. Returns an empty list for a first-time shopper. Use this at the start of a purchase: if they are known, greet them by name and pass their id to create_cart; if not, carry on and create them at checkout.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/customers",
    "path_parameters": {},
    "query_parameters": {
      "phone": {
        "type": "string",
        "required": false,
        "description": "WhatsApp phone number of the current conversation, injected by the runtime.",
        "binding": {
          "kind": "macro",
          "macro": "WHATSAPP_PHONE_NUMBER"
        }
      },
      "email": {
        "type": "string",
        "required": false,
        "description": "Look up by email instead. Only use if the customer volunteers one and the phone lookup found nothing."
      }
    },
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "create_cart",
  "description": "Start a new empty shopping cart and return its id. Call this once at the beginning of a purchase, then use add_cart_item. Do not create a second cart for the same conversation unless the customer asks to start over.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/carts",
    "path_parameters": {},
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "customer_id": {
          "type": "string",
          "description": "Customer id from create_customer. Pass it when you already know who you are talking to, so the order is linked to them without asking again at checkout. Omit it if the customer has not been identified yet."
        }
      },
      "required": []
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "add_cart_item",
  "description": "Add a product variant to the cart. Returns the cart with recomputed subtotal, discount, shipping, tax and total. The variant is the exact configuration (colour + storage/memory), so confirm which one the customer means before calling. If the store is enforcing stock and the customer asked for more than is available, this returns a 409 telling you the available quantity — offer them that amount instead.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/carts/{cart_id}/items",
    "path_parameters": {
      "cart_id": {
        "type": "string",
        "description": "Cart id from create_cart, e.g. cart_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "variant_id": {
          "type": "string",
          "description": "VARIANT id (starts with var_), taken from a product's variants array. Not the product id."
        },
        "quantity": {
          "type": "integer",
          "description": "How many units to add. Adding a variant already in the cart increases its quantity."
        }
      },
      "required": [
        "variant_id",
        "quantity"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "get_cart",
  "description": "Read the current contents and totals of a cart. Use before checkout to confirm the order back to the customer. Totals are recalculated on every read, so an expired discount stops applying.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/carts/{cart_id}",
    "path_parameters": {
      "cart_id": {
        "type": "string",
        "description": "Cart id, e.g. cart_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "apply_discount",
  "description": "Apply a promotional code to the cart. Returns 422 with a specific reason if the code is unknown, expired, or the cart is below its minimum spend — relay that reason to the customer rather than just saying it failed.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/carts/{cart_id}/discounts",
    "path_parameters": {
      "cart_id": {
        "type": "string",
        "description": "Cart id, e.g. cart_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "code": {
          "type": "string",
          "description": "Discount code exactly as the customer gave it. Case-insensitive."
        }
      },
      "required": [
        "code"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "get_shipping_rates",
  "description": "Get the available delivery options for a cart, with price and estimated days. Present these to the customer and let them choose before calling select_shipping. An option priced at zero means free shipping was earned.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/shipping/rates",
    "path_parameters": {},
    "query_parameters": {
      "cart_id": {
        "type": "string",
        "description": "Cart to quote shipping for.",
        "required": true
      },
      "postal_code": {
        "type": "string",
        "description": "Destination postal code, if the customer has given one.",
        "required": false
      }
    },
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "select_shipping",
  "description": "Record the delivery method the customer chose. Must be called before create_checkout, otherwise checkout will report shipping_method as missing.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/carts/{cart_id}/shipping",
    "path_parameters": {
      "cart_id": {
        "type": "string",
        "description": "Cart id, e.g. cart_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "method_code": {
          "type": "string",
          "description": "Shipping method code from get_shipping_rates, e.g. standard or express."
        },
        "postal_code": {
          "type": "string",
          "description": "Destination postal code, if known."
        }
      },
      "required": [
        "method_code"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "create_checkout",
  "description": "Create a checkout from the cart once you have the delivery address. The response includes ready_to_complete and a missing[] list — if ready_to_complete is false, ask the customer only for what is in missing[], then call update_checkout or start again. Do not call complete_checkout until ready_to_complete is true.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/checkouts",
    "path_parameters": {},
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "cart_id": {
          "type": "string",
          "description": "Cart to convert into an order."
        },
        "customer_id": {
          "type": "string",
          "description": "Customer id from create_customer."
        },
        "phone": {
          "type": "string",
          "description": "WhatsApp phone number of the current conversation, injected by the runtime.",
          "binding": {
            "kind": "macro",
            "macro": "WHATSAPP_PHONE_NUMBER"
          }
        },
        "shipping_method_code": {
          "type": "string",
          "description": "Delivery method code, same value passed to select_shipping."
        },
        "shipping_address": {
          "type": "object",
          "description": "Delivery address. line1, city, postal_code and country are required; country is a 2-letter code such as BR.",
          "properties": {
            "line1": "{\"type\":\"string\",\"description\":\"Street and number.\"}",
            "line2": "{\"type\":\"string\",\"description\":\"Apartment, block or complement.\"}",
            "district": "{\"type\":\"string\",\"description\":\"Neighbourhood or district.\"}",
            "city": "{\"type\":\"string\",\"description\":\"City name.\"}",
            "state": "{\"type\":\"string\",\"description\":\"State or region code, e.g. SP.\"}",
            "postal_code": "{\"type\":\"string\",\"description\":\"Postal code, e.g. 01310-100.\"}",
            "country": "{\"type\":\"string\",\"description\":\"Two-letter country code.\",\"binding\":{\"kind\":\"default\",\"value\":\"BR\"}}"
          }
        },
        "email": {
          "type": "string",
          "description": "Email for the order confirmation, if the customer has given one. Optional — the phone number is enough."
        }
      },
      "required": [
        "cart_id",
        "shipping_address"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "get_checkout",
  "description": "Read a checkout back, including its totals, ready_to_complete flag and the missing[] list. Use it after update_checkout to confirm the checkout is now complete before calling complete_checkout, instead of assuming your update worked.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/checkouts/{checkout_id}",
    "path_parameters": {
      "checkout_id": {
        "type": "string",
        "description": "Checkout id, e.g. chk_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "update_checkout",
  "description": "Supply details a checkout is still missing, such as the address or the delivery method. Use this in response to the missing[] list from create_checkout instead of creating a second checkout.",
  "request_definition": {
    "method": "PATCH",
    "path": "/v1/checkouts/{checkout_id}",
    "path_parameters": {
      "checkout_id": {
        "type": "string",
        "description": "Checkout id, e.g. chk_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "email": {
          "type": "string",
          "description": "Customer email, if they provide one."
        },
        "shipping_method_code": {
          "type": "string",
          "description": "Delivery method code."
        },
        "shipping_address": {
          "type": "object",
          "description": "Delivery address, same shape as create_checkout.",
          "properties": {
            "line1": "{\"type\":\"string\",\"description\":\"Street and number.\"}",
            "city": "{\"type\":\"string\",\"description\":\"City name.\"}",
            "state": "{\"type\":\"string\",\"description\":\"State or region code.\"}",
            "postal_code": "{\"type\":\"string\",\"description\":\"Postal code.\"}",
            "country": "{\"type\":\"string\",\"description\":\"Two-letter country code.\",\"binding\":{\"kind\":\"default\",\"value\":\"BR\"}}"
          }
        },
        "customer_id": {
          "type": "string",
          "description": "Link this checkout to a customer created with create_customer."
        }
      },
      "required": []
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "complete_checkout",
  "description": "Place the order. Only call this once ready_to_complete is true, and only once per checkout — calling it again returns the same order rather than creating a second one. Returns the order id and human-readable order number to give the customer.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/checkouts/{checkout_id}/complete",
    "path_parameters": {
      "checkout_id": {
        "type": "string",
        "description": "Checkout id, e.g. chk_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {},
      "required": []
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "create_payment",
  "description": "Start payment for an order. For method=pix the response contains details.pix_code — send that code to the customer so they can pay. For method=link the response contains details.checkout_url. The payment starts as pending; poll get_payment to see when it settles. NEVER ask the customer for card numbers in chat.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/payments",
    "path_parameters": {},
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "order_id": {
          "type": "string",
          "description": "Order id from complete_checkout."
        },
        "method": {
          "type": "string",
          "description": "One of pix, link, card or boleto. Use pix or link for WhatsApp — never ask a customer to type card details into chat."
        },
        "token": {
          "type": "string",
          "description": "Card number or token. Only used when method is \"card\". Tokens listed in the store’s decline_tokens always fail with a specific reason, which is how you reproduce a declined payment on purpose."
        },
        "return_url": {
          "type": "string",
          "description": "Where a hosted payment link should send the shopper after paying. Only used when method is \"link\"."
        }
      },
      "required": [
        "order_id",
        "method"
      ]
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "get_payment",
  "description": "Check the status of a payment: pending, succeeded, failed or expired. Use when the customer says they have paid, to confirm before telling them the order is on its way.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/payments/{payment_id}",
    "path_parameters": {
      "payment_id": {
        "type": "string",
        "description": "Payment id, e.g. pay_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "find_my_orders",
  "description": "List the orders belonging to the person you are chatting with. Their phone number is filled in automatically — do not ask for it. Use this whenever the customer asks about 'my order', a delivery, or their purchase history.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/orders",
    "path_parameters": {},
    "query_parameters": {
      "phone": {
        "type": "string",
        "description": "WhatsApp phone number of the current conversation, injected by the runtime.",
        "required": true,
        "binding": {
          "kind": "macro",
          "macro": "WHATSAPP_PHONE_NUMBER"
        }
      },
      "limit": {
        "type": "integer",
        "description": "Maximum orders to return. Use 5 or fewer in chat.",
        "required": false
      },
      "status": {
        "type": "string",
        "description": "Filter to one order status: pending, paid, processing, shipped, delivered, cancelled or refunded. Use when the customer asks specifically about, say, orders still on the way.",
        "required": false
      }
    },
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "get_order",
  "description": "Get one order with its items, totals, payment status, fulfilment status and any shipments. Use to answer 'where is my order' — the shipments array carries the tracking code.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/orders/{order_id}",
    "path_parameters": {
      "order_id": {
        "type": "string",
        "description": "Order id, e.g. ord_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "track_shipment",
  "description": "Get the tracking status and event history for a shipment. Summarise the most recent event for the customer rather than reading out the whole history.",
  "request_definition": {
    "method": "GET",
    "path": "/v1/shipments/{shipment_id}",
    "path_parameters": {
      "shipment_id": {
        "type": "string",
        "description": "Shipment id from an order's shipments array, e.g. shp_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": null
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "name": "cancel_order",
  "description": "Cancel an order. Only works before it ships — a shipped or delivered order returns 409, in which case tell the customer a return is needed instead of a cancellation, and hand off to a human.",
  "request_definition": {
    "method": "POST",
    "path": "/v1/orders/{order_id}/cancel",
    "path_parameters": {
      "order_id": {
        "type": "string",
        "description": "Order id, e.g. ord_1a2b3c."
      }
    },
    "query_parameters": {},
    "headers": {},
    "body": {
      "content_type": "application/json",
      "params": {
        "reason": {
          "type": "string",
          "description": "Short reason the customer gave for cancelling."
        }
      },
      "required": []
    }
  },
  "user_auth_required": false,
  "user_auth_action_config": null
}

{
  "input": "{\"q\":\"fone bluetooth\",\"limit\":3}"
}

{
  "input": "{\"limit\":5}"
}

{
  "title": "accessory-attach",
  "description": "…one line describing when this skill applies…",
  "skill": "…replace with the edited markdown body…"
}

{
  "api_key": {
    "headers": [
      {
        "field_name": "X-API-Key",
        "value": "{{SHOP_API_KEY}}",
        "prefix": ""
      }
    ]
  }
}

{
  "oauth2_client_credentials": {
    "token_url": "https://auth.example.com/oauth2/token",
    "client_id": "{{OAUTH_CLIENT_ID}}",
    "client_secret": "{{OAUTH_CLIENT_SECRET}}",
    "scopes_to_request": [
      "catalog.read",
      "orders.write"
    ]
  }
}

{
  "name": "elecstore",
  "description": "ElecStore electronics store. Catalogue, cart, checkout, PIX payment, and order and delivery status. Updated during the workshop.\n",
  "base_url": "{{SHOP_API}}",
  "auth_type": "API_KEY",
  "requires_certificate": false,
  "auth_config": {
    "api_key": {
      "headers": [
        {
          "field_name": "X-API-Key",
          "value": "{{SHOP_API_KEY}}",
          "prefix": ""
        }
      ]
    }
  }
}

{
  "to": "{{CONSUMER_PHONE_DIGITS}}",
  "event": {
    "type": "payment.succeeded",
    "description": "The PIX payment for order ord_demo1 has been confirmed. Tell the customer the order is paid and already being picked, and give them the order number. Do not offer any further products in this message.",
    "payload": "{\"order_id\":\"ord_demo1\",\"payment_id\":\"pay_demo1\",\"method\":\"pix\",\"amount_cents\":29900,\"currency\":\"BRL\"}"
  }
}

{
  "to": "{{CONSUMER_PHONE_DIGITS}}",
  "event": {
    "type": "shipment.updated",
    "description": "Order ord_demo1 went out for delivery today. Tell the customer, and give the tracking code BR123456789BR on its own line so they can copy it.",
    "payload": "{\"order_id\":\"ord_demo1\",\"shipment_id\":\"shp_demo1\",\"status\":\"out_for_delivery\",\"tracking_code\":\"BR123456789BR\"}"
  }
}

{
  "to": "{{CONSUMER_PHONE_DIGITS}}",
  "event": {
    "type": "order.cancelled",
    "description": "Order ord_demo1 was cancelled at the customer request. Confirm the cancellation and say the PIX refund lands within 5 business days. Do not promise any other timescale.",
    "payload": "{\"order_id\":\"ord_demo1\",\"reason\":\"customer_request\",\"refund_status\":\"pending\"}"
  }
}

{
  "messaging_product": "whatsapp",
  "action": "take",
  "to": "{{CONSUMER_PHONE}}",
  "metadata": "Human agent stepping in"
}

{
  "messaging_product": "whatsapp",
  "action": "pass",
  "to": "{{CONSUMER_PHONE}}",
  "control_pass": {
    "target_role": "ai_agent"
  },
  "metadata": "Human handling complete — returning to the agent."
}

{
  "messaging_product": "whatsapp",
  "action": "release",
  "to": "{{CONSUMER_PHONE}}",
  "metadata": "Conversation complete."
}
